/* Material-bounded discovery of NATURAL Primals.
 * This algorithm does not store known recipe strings and does not know which
 * fixture is being tested. Every state is generated by UniversalEngine.apply.
 * It explores R/C/S transitions and checks item identity, affix families,
 * a natural resistance and one *legal* Mystic replacement. No S/P final goals.
 *
 * Cost ordering: Souls, Crucibles, number of steps, then fewer Mystic edits.
 * It reports truncation honestly, never claiming mathematical optimality.
 */
function sameOrBetter(a,b){
 return a.souls<=b.souls&&a.crucibles<=b.crucibles&&a.steps<=b.steps;
}
const min=(x,y)=>Math.min(x,y);
export function searchBudgetPrimal(engine,{
 itemId,targetItemId,seed,goals=[],budget={},maxSteps=18,maxNodes=1000000,
 allowMystic=true,requireResistance=false,allowConvert=true,onProgress=null
}={}){
 const source=engine.item(itemId),target=engine.item(targetItemId);
 if(!source||!target)throw Error('El objeto actual y el objetivo deben estar en la base de datos.');
 if(!Number.isInteger(seed)||seed<0||seed>4294967295)throw Error('Es necesaria una seed válida.');
 const wanted=[...new Set(goals)].filter(Boolean);
 if(!wanted.length)throw Error('Selecciona los afijos necesarios.');
 const limits={
  souls:Math.min(2000,Math.max(0,Math.floor(Number(budget.souls)||0))),
  crucibles:Math.min(100,Math.max(0,Math.floor(Number(budget.crucibles)||0))),
  deathBreaths:Math.min(2000,Math.max(0,Math.floor(Number(budget.deathBreaths)||0))),
  actMaterialsEach:Math.min(500,Math.max(0,Math.floor(Number(budget.actMaterialsEach)||0)))
 };
 maxSteps=min(30,Math.max(1,Math.floor(maxSteps)));
 maxNodes=min(3000000,Math.max(1000,Math.floor(maxNodes)));
 const maxR=min(12,Math.floor(limits.souls/50),Math.floor(limits.actMaterialsEach/5));
 const maxC=allowConvert?min(25,Math.floor(limits.souls/10),Math.floor(limits.deathBreaths/10)):0;
 const maxS=min(30,limits.crucibles);
 const candidates=engine.candidateAffixes(target);
 const substitutions=new Map();
 for(const family of wanted){
  const pool=candidates.filter(a=>a.pick_kind===0&&
   (a.label===family||a.label.startsWith(family+' '))&&
   engine.idIndex.has(a.id));
  substitutions.set(family,pool);
 }
 function goal(r){
  if(r.itemId!==target.id||r.quality!=='primal')return null;
  const have=new Set(r.affixes.map(a=>a.stem));
  const missing=wanted.filter(x=>!have.has(x));
  if(missing.length>(allowMystic?1:0))return null;
  const secondary=r.affixes.filter(a=>a.kind===1&&
    /Resist$/.test(a.stem)).map(a=>a.stem);
  if(requireResistance&&!secondary.length)return null;
  let mystic=null;
  if(missing.length){
   const family=missing[0],possible=substitutions.get(family)||[];
   if(!possible.length)return null;
   const held=wanted.filter(g=>have.has(g));
   for(const old of r.affixes){
    if(old.kind!==0||old.socket||held.includes(old.stem))continue;
    const other=r.affixes.filter(x=>x!==old).map(x=>engine.idIndex.get(x.id));
    const allowed=possible.some(newAffix=>{
      const idx=engine.idIndex.get(newAffix.id);
      return idx!==undefined&&!engine.excluded(idx,other)&&engine.fits(idx,other);
    });
    if(allowed){mystic={replace:old.stem,with:family};break;}
   }
   if(!mystic)return null;
  }
  return {mystic,secondary,values:r.lines.map(x=>({stem:x.stem,value:x.value})),affixes:r.affixes.map(x=>({stem:x.stem,kind:x.kind}))};
 }
 const counts={visited:0,goalsFound:0,primalChecked:0};
 let best=null,truncated=false;
 const costs=(r,c,s,path)=>({souls:50*r+10*c,actMaterialsEach:5*r,
   deathBreaths:10*c,crucibles:s,steps:path.length,reforges:r,converts:c,sanctifies:s});
 const better=(a,b)=>!b||a.materials.souls<b.materials.souls||
  a.materials.souls===b.materials.souls&&(a.materials.crucibles<b.materials.crucibles||
   a.materials.crucibles===b.materials.crucibles&&(a.materials.steps<b.materials.steps||
     a.materials.steps===b.materials.steps&&!a.goal.mystic&&!!b.goal.mystic));
 // The set of legal operations remains unchanged; no hidden fixture lookup.
 function dfs(item,seed,path,r,c,s,usedSouls){
  counts.visited++;
  if(counts.visited>maxNodes){truncated=true;return;}
  if(counts.visited%100000===0&&onProgress)onProgress({...counts,best:best?.path||null});
  if(path.length>=maxSteps||usedSouls+50>limits.souls||r>=maxR&&c>=maxC&&s>=maxS)return;
  // A final Reforge costs at least 50 Souls, and a C to return to target costs
  // an additional 10 if current set identity differs.
  if(item.id!==target.id&&usedSouls+60>limits.souls)return;
  for(const op of ['R','C','S']){
   const nr=r+(op==='R'),nc=c+(op==='C'),ns=s+(op==='S');
   const souls=usedSouls+(op==='R'?50:op==='C'?10:0);
   if(nr>maxR||nc>maxC||ns>maxS||souls>limits.souls||
      nr*5>limits.actMaterialsEach||nc*10>limits.deathBreaths)continue;
   if(op==='C'&&(!allowConvert||!item.set_id))continue;
   let result;
   try{result=engine.apply(item,seed,op)}catch{continue}
   const nextPath=path+op;
   if(op==='R'&&result.quality==='primal'){
    counts.primalChecked++;
    const valid=goal(result);
    if(valid){
     counts.goalsFound++;
     const m=costs(nr,nc,ns,nextPath);
     const obj={path:nextPath,materials:m,goal:valid,lastSeed:result.seed};
     if(better(obj,best)){
      let cur=source,currentSeed=Number(seed),unused=0;
      // Replay from the ORIGINAL recovered seed (not local DFS node), so each
      // visible checkpoint comes from the full and exact executed path.
      cur=source;currentSeed=Number(startSeed);
      const steps=[];
      for(const symbol of nextPath){
       const step=engine.apply(cur,currentSeed,symbol);
       steps.push({op:symbol,item:step.item,quality:step.quality,seed:step.seed,
        lines:step.lines.map(x=>({stem:x.stem,value:x.value})),
        affixes:step.affixes.map(x=>x.stem)});
       cur=engine.item(step.itemId);currentSeed=step.seed;
      }
      obj.steps=steps;best=obj;
     }
    }
   }
   if(truncated)return;
   if(nextPath.length<maxSteps&&souls+50<=limits.souls){
    // A cheapest material-constrained route cannot use a Primal generated by
    // Sanctify as final; such states can be intermediate only.
    dfs(engine.item(result.itemId),result.seed,nextPath,nr,nc,ns,souls);
   }
   if(truncated)return;
  }
 }
 const startSeed=seed;
 dfs(source,seed,'',0,0,0,0);
 return {best,visited:counts.visited,goalsFound:counts.goalsFound,primalChecked:counts.primalChecked,truncated,
   budget:limits,limits:{maxR,maxC,maxS,maxSteps,maxNodes},
   caveat:'All routes are simulator predictions. Check each in the console; material-budget search may be truncated.'};
}
